const pageHtml = $json.data || '';
const webhook   = $('Application Webhook').first().json.body;
const jobUrl    = webhook.job_url       || '';
const jobTitle  = webhook.job_title     || 'Data Science Position';
const company   = webhook.company_name  || 'Unknown Company';

// --- UPDATE THESE FIELDS WITH YOUR REAL INFO ---
const profile = {
  first_name:          'Yahya',
  last_name:           'Ahmed',
  full_name:           'Yahya Ahmed',
  email:               'yahyaahmedafro@gmail.com',
  phone:               'YOUR_PHONE_NUMBER',
  address:             'YOUR_FULL_ADDRESS',
  city:                'YOUR_CITY',
  state:               'YOUR_STATE',
  zip:                 'YOUR_ZIP',
  country:             'United States',
  nationality:         'YOUR_NATIONALITY',
  linkedin:            'https://linkedin.com/in/YOUR_USERNAME',
  github:              '',
  portfolio:           '',
  current_title:       'Data Science Professional',
  years_experience:    '3+',
  education_level:     'Bachelor of Science',
  field_of_study:      'Data Science / Statistics',
  university:          'YOUR_UNIVERSITY',
  graduation_year:     'YOUR_GRAD_YEAR',
  gpa:                 'YOUR_GPA',
  skills:              'Python, SQL, Machine Learning, TensorFlow, scikit-learn, pandas, NumPy, R, Tableau, Power BI, Excel, Git, AWS',
  certifications:      'YOUR_CERTIFICATIONS',
  languages:           'English (Fluent)',
  work_authorization:  'Authorized to work in the United States',
  visa_sponsorship:    'No',
  willing_to_relocate: 'Yes',
  willing_to_travel:   'Yes, up to 25%',
  desired_salary:      'Negotiable based on role and benefits',
  employment_type:     'Full-time',
  start_date:          'Immediately available',
  referral_source:     'LinkedIn',
  veteran_status:      'Not a veteran',
  disability:          'No disability'
};
// -----------------------------------------------

const html = pageHtml.substring(0, 12000);

const userMsg = `Fill out this job application for the candidate.\n\nJOB: ${jobTitle} at ${company}\nURL: ${jobUrl}\n\nCANDIDATE PROFILE:\n${JSON.stringify(profile, null, 2)}\n\nPAGE HTML:\n${html}\n\nRespond with ONLY this JSON structure:\n{\n  "form_type": "simple_post" or "complex",\n  "form_action": "URL if simple_post else null",\n  "form_method": "POST" or "GET",\n  "fields": { "input_field_name_or_label": "value_to_enter" },\n  "cover_letter": "Two tailored paragraphs for this specific role",\n  "step_by_step": ["Step 1...", "Step 2..."],\n  "notes": "Anything important the candidate should know",\n  "estimated_minutes": 15\n}`;

const openai_body = JSON.stringify({
  model: 'gpt-4o-mini',
  messages: [
    { role: 'system', content: 'You are a job application assistant. Respond ONLY with valid JSON.' },
    { role: 'user',   content: userMsg }
  ],
  response_format: { type: 'json_object' },
  max_tokens: 2500
});

return [{ json: { openai_body, job_url: jobUrl, job_title: jobTitle, company } }];

const aiResp = $input.first().json;
const raw = aiResp.choices[0].message.content;
let analysis;
try {
  analysis = JSON.parse(raw);
} catch(e) {
  analysis = {
    form_type:         'complex',
    fields:            {},
    cover_letter:      '',
    step_by_step:      ['Visit the URL', 'Fill in your details manually'],
    notes:             'AI could not parse the form structure.',
    estimated_minutes: 15
  };
}

const prev   = $('Build Analysis Prompt').first().json;
const fields = analysis.fields || {};

const fieldLines = Object.entries(fields)
  .map(([k, v]) => `• *${k}:* ${v}`)
  .join('\n');

const steps = (analysis.step_by_step || [])
  .map((s, i) => `${i + 1}. ${s}`)
  .join('\n');

return [{
  json: {
    form_type:         analysis.form_type         || 'complex',
    form_action:       analysis.form_action        || null,
    fields,
    field_lines:       fieldLines,
    cover_letter:      analysis.cover_letter       || '',
    steps,
    notes:             analysis.notes              || '',
    estimated_minutes: analysis.estimated_minutes  || 15,
    job_url:           prev.job_url,
    job_title:         prev.job_title,
    company:           prev.company
  }
}];
